// SPDX-License-Identifier: MIT
pragma solidity >=0.6.11 <0.9.0;
pragma experimental ABIEncoderV2;
interface IBase { event Ping(address indexed actor); }
abstract contract Base is IBase { event Seen(uint n) anonymous; }
library Lib { event FromLibrary(address indexed sender); function f() internal { emit FromLibrary(msg.sender); } }
contract Derived is Base {
 enum Status { One, Two }
 struct Nested { address actor; uint256[2] fixedValues; }
 struct Item { Nested inner; Status status; address payable destination; }
 event Ping(uint indexed n); event Changed(uint first, address indexed second);
 event Complex(Item item, Item[] items, bytes32 indexed key);
 event Opaque(function(uint256) external returns (uint256) callback);
 function f() public { emit Ping(msg.sender); Lib.f(); }
}
